		"text": "Response\n\nAbridged below to the fields a renderer uses. Each row is a SELECT * passthrough, so the real objects carry every stored column &mdash; timestamps, provenance, reinforcement counters, validity windows &mdash; alongside the derived fields named here.\n\n{\n  \"nodes\": [\n    {\n      \"id\": \"node_7c\",\n      \"label\": \"Postgres\",\n      \"category\": \"tool\",\n      \"state\": \"active\",\n      \"summary\": \"Chosen for the new service.\",\n      \"revision\": 2,\n      \"project_id\": null,\n      \"project_name\": null,\n      \"project_category\": null,\n      \"cluster\": \"skills_tech\",\n      \"cluster_id\": \"skills_tech\",\n      \"cluster_label\": \"Skills & Tech\",\n      \"cluster_color\": \"#22c55e\",\n      \"visual_type\": \"node\",\n      \"x\": -664,\n      \"y\": 341,\n      \"radius\": 18,\n      \"importance_rank\": 2,\n      \"importance_score\": 56,\n      \"slices\": [\n        { \"id\": \"slice_1b\", \"node_id\": \"node_7c\", \"text\": \"Picked over MySQL for JSONB.\",\n          \"kind\": \"decision\", \"is_current\": 1, \"created_at\": 1756200000000 }\n      ],\n      \"events\": [\n        { \"id\": \"event_9f\", \"node_id\": \"node_7c\", \"action\": \"decided\", \"text\": \"Datastore settled.\",\n          \"importance\": \"ordinary\", \"happened_at\": 1756118400000, \"created_at\": 1756200000000 }\n      ]\n    }\n  ],\n  \"pages\": [\n    { \"id\": \"page_2a\", \"title\": \"Service rewrite\", \"category\": \"project\",\n      \"summary\": \"Datastore choice and the migration order.\",\n      \"cluster\": \"projects_systems\", \"visual_type\": \"page\",\n      \"x\": 24, \"y\": -52, \"radius\": 44, \"importance_rank\": 1, \"importance_score\": 141 }\n  ],\n  \"clusters\": [\n    { \"id\": \"skills_tech\", \"label\": \"Skills & Tech\", \"display_label\": \"Skills & Tech · 4\",\n      \"color\": \"#22c55e\", \"x\": -700, \"y\": 300,\n      \"radius\": 190, \"radius_x\": 220, \"radius_y\": 148, \"label_x\": -700, \"label_y\": 116,\n      \"count\": 4, \"total_count\": 5, \"candidate_count\": 1 }\n  ],\n  \"edges\": [\n    { \"id\": \"edge_5d\", \"from_node\": \"node_7c\", \"to_node\": \"node_3e\", \"type\": \"USED_BY\",\n      \"weight\": 1, \"fact\": \"The reporting service runs on Postgres.\",\n      \"valid_at\": 1756118400000, \"invalid_at\": null, \"project_id\": null }\n  ],\n  \"candidates\": [\n    { \"id\": \"candidate_4a\", \"label\": \"pgBouncer\", \"category\": \"interest\", \"summary\": null,\n      \"strength\": \"weak\", \"status\": \"pending\",\n      \"visual_type\": \"candidate\", \"x\": -712, \"y\": 372, \"radius\": 13 }\n  ],\n  \"projects\": [\n    { \"project_id\": \"reporting\", \"project_name\": \"Reporting\",\n      \"nodes\": 12, \"pages\": 3, \"slices\": 41, \"events\": 8, \"edges\": 9, \"candidates\": 2 }\n  ],\n  \"legacy_project_scopes\": [],\n  \"scope_model\": {\n    \"default_recall\": \"global\",\n    \"project_recall\": [\"project_only\", \"project_then_global\"],\n    \"global_rows_use_null_project_id\": true\n  },\n  \"stats\": { \"nodes\": 34, \"pages\": 6, \"clusters\": 7,\n             \"slices\": 118, \"events\": 22, \"edges\": 27, \"candidates\": 5 },\n  \"model\": \"@cf/qwen/qwen3-30b-a3b-fp8\",\n  \"models\": [\"@cf/meta/llama-3.1-8b-instruct-fp8\", \"@cf/qwen/qwen3-30b-a3b-fp8\"]\n}"
